/** Generated by quail. */
import { test } from '@playwright/test'
import { opGoto, opClick, opFill, opPress, opSeen } from './prims'

test('@journey:negative @smoke Rejects malformed email in event registration', async ({ page }) => {
  await opGoto(page, '/events')
  await opClick(page, 'link', 'QA Community Meetup April 2026')
  await opFill(page, 'Name', 'Alex Rivera')
  await opFill(page, 'Email', 'not-an-email')
  await opClick(page, 'button', 'Register')
  await opSeen(page, 'alert', 'Please enter a valid email address')
})
